        STAKING_REWARDS.withdraw(amount);

        uint256 received;
        if (toUnderlying) {
            received = YEARN_VAULT.withdraw(amount, recipient, maxSlippage);
        } else {
            received = amount;
            IERC20(YEARN_VAULT).safeTransfer(recipient, amount);
        }

        return (amount, received);
    }

